#!/usr/bin/env bash
# le-sync LEZ environment (Sprint 6, M0). Source it, do not execute it:
#
#   source scripts/lez-env.sh
#
# Runs from the LEZ project directory (default ./lez, generated by `lgs new`).
# Override before sourcing: LEZ_DIR (project dir), LEZ_PROGRAM (program to deploy, default lez_counter),
# LEZ_BIN (path of the built program .bin), LEZ_IDL (IDL file), LEZ_WAIT (seconds to wait for a block, default 20).
# RISC0_DEV_MODE=1 is set only inside these functions, for the local sequencer. Fake receipts: never
# use them for a real claim. Unset it again for anything else.
#
# Commands after sourcing:
#   lez_check             versions and prerequisites, no changes made
#   lez_new               create the project in $LEZ_DIR (once)
#   lez_setup             fetch and build LEZ, SPEL and the wallet (slow on a cold cache), then doctor
#   lez_build             build the guest programs on the host toolchain (--guest local)
#   lez_up                start the local sequencer (port 3040) and show its status
#   lez_down              stop the local sequencer
#   lez_deploy [name]     deploy all programs, or one by name (default: $LEZ_PROGRAM)
#   lez_authority         fund the default wallet account (topup) and keep its ID in $LEZ_AUTH
#   lez_init              send `initialize` to the program (creates the counter PDA)
#   lez_incr [n]          send `increment` by n (default 1)
#   lez_read              read the counter PDA ($LEZ_PDA)
#   lez_call              lez_init, wait, lez_incr, wait, lez_read (the M0 done-when)
#   lez_record            print the versions, pins and image IDs to paste into docs/lez-setup.md
#   lez_all               up, deploy, call (stack must be built)

if [ "${BASH_SOURCE[0]}" = "$0" ]; then
  echo "source this file: source scripts/lez-env.sh" >&2
  exit 2
fi

LEZ_DIR="${LEZ_DIR:-./lez}"
LEZ_PROGRAM="${LEZ_PROGRAM:-lez_counter}"
LEZ_IDL="${LEZ_IDL:-idl/${LEZ_PROGRAM}.json}"
LEZ_BIN="${LEZ_BIN:-target/riscv-guest/example_program_deployment_methods/example_program_deployment_programs/riscv32im-risc0-zkvm-elf/release/${LEZ_PROGRAM}.bin}"
LEZ_WAIT="${LEZ_WAIT:-20}"
LEZ_AUTH="${LEZ_AUTH:-}"
LEZ_PDA="${LEZ_PDA:-}"

# lgs and logos-scaffold are the same tool
_lez_bin() { command -v lgs >/dev/null 2>&1 && echo lgs || echo logos-scaffold; }
_lez_in() { ( cd "$LEZ_DIR" && "$@" ); }
_lez_scaf() { local b; b="$(_lez_bin)"; _lez_in env RISC0_DEV_MODE=1 "$b" "$@"; }

lez_check() {
  local ok=0 t
  for t in git rustc cargo curl lsof; do
    if command -v "$t" >/dev/null 2>&1; then echo "ok   $t  $("$t" --version 2>&1 | head -1)"; else echo "MISSING $t"; ok=1; fi
  done
  if command -v lgs >/dev/null 2>&1 || command -v logos-scaffold >/dev/null 2>&1; then
    echo "ok   $(_lez_bin)  $($(_lez_bin) --version 2>&1 | head -1)"
  else echo "MISSING lgs / logos-scaffold"; ok=1; fi
  if command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1; then echo "ok   docker daemon running"
  elif command -v podman >/dev/null 2>&1; then echo "ok   podman present"
  else echo "MISSING docker or podman (daemon must run)"; ok=1; fi
  if command -v rzup >/dev/null 2>&1; then rzup show 2>&1 | head -12; else echo "MISSING rzup (risc0 toolchain)"; ok=1; fi
  return $ok
}

lez_new() {
  if [ -d "$LEZ_DIR" ]; then echo "$LEZ_DIR exists, not touching it" >&2; return 1; fi
  "$(_lez_bin)" new "$LEZ_DIR" --template lez-framework
}

lez_setup() { _lez_scaf setup && _lez_scaf doctor; }
# --guest local: the Docker guest build failed on this Mac (no arm64 manifest). Image IDs from a local build
# may differ from a Docker/Linux build, so compare before pinning one.
lez_build() { _lez_scaf build --guest local; }
lez_up()    { _lez_scaf localnet start && _lez_scaf localnet status; }
lez_down()  { _lez_scaf localnet stop; }

lez_deploy() { _lez_scaf deploy "${1:-$LEZ_PROGRAM}"; }

# Wallet env: the scaffold keeps its wallet inside the project
_lez_wenv() {
  local home; home="$(cd "$LEZ_DIR" && pwd)/.scaffold/wallet"
  export NSSA_WALLET_HOME_DIR="$home" LEE_WALLET_HOME_DIR="$home"
}

# SPEL CLI through the scaffold. The template's own client binary (src/bin/run_*.rs) is a stub
# that submits nothing; spel is the working call path.
_lez_spel() { _lez_wenv; _lez_in "$(_lez_bin)" spel -- --idl "$LEZ_IDL" --program "$LEZ_BIN" -- "$@"; }

lez_authority() {
  _lez_wenv
  local out
  out="$(_lez_in "$(_lez_bin)" wallet topup 2>&1)" || { echo "$out" >&2; return 1; }
  echo "$out"
  LEZ_AUTH="$(printf '%s\n' "$out" | sed -n 's#.*Address: Public/\([A-Za-z0-9]*\).*#\1#p' | head -1)"
  [ -n "$LEZ_AUTH" ] && echo "LEZ_AUTH=$LEZ_AUTH" || { echo "could not read the account ID, set LEZ_AUTH by hand" >&2; return 1; }
}

lez_init() {
  [ -n "$LEZ_AUTH" ] || { echo "run lez_authority first, or set LEZ_AUTH" >&2; return 1; }
  local out; out="$(_lez_spel initialize --authority "$LEZ_AUTH" 2>&1)"; local rc=$?
  echo "$out"
  LEZ_PDA="$(printf '%s\n' "$out" | sed -n 's#.*counter → \([A-Za-z0-9]*\) (PDA).*#\1#p' | head -1)"
  [ -n "$LEZ_PDA" ] && echo "LEZ_PDA=$LEZ_PDA"
  return $rc
}

lez_incr() {
  [ -n "$LEZ_AUTH" ] || { echo "run lez_authority first, or set LEZ_AUTH" >&2; return 1; }
  _lez_spel increment --amount "${1:-1}" --authority "$LEZ_AUTH"
}

lez_read() {
  [ -n "$LEZ_PDA" ] || { echo "run lez_init first, or set LEZ_PDA" >&2; return 1; }
  _lez_in "$(_lez_bin)" wallet -- account get --account-id "Public/$LEZ_PDA"
}

lez_call() {
  lez_authority && lez_init && sleep "$LEZ_WAIT" && lez_read && lez_incr 1 && sleep "$LEZ_WAIT" && lez_read
}

lez_record() {
  echo "date:        $(date -u +%FT%TZ)"
  echo "os:          $(uname -sm)"
  echo "scaffold:    $($(_lez_bin) --version 2>&1 | head -1)"
  echo "rustc:       $(rustc --version)"
  command -v rzup >/dev/null 2>&1 && { echo "rzup:"; rzup show 2>&1 | sed 's/^/  /'; }
  if [ -f "$LEZ_DIR/scaffold.toml" ]; then echo "scaffold.toml pins:"; sed 's/^/  /' "$LEZ_DIR/scaffold.toml"; fi
  echo "image IDs (from the build output; also compare with a Linux build):"
  _lez_in sh -c 'grep -rhoE "[A-Za-z_]+(_ID|image_id)[^\n]{0,90}" target/riscv-guest 2>/dev/null | head -10' || true
}

lez_all() { lez_up && lez_deploy && lez_call; }